-- Catalog accuracy fixes, 2026-10-02. Idempotent: safe to re-run.
-- Paste into the Supabase SQL Editor and run once.
--
-- 1. Adds kieró Refining Enzyme Cleanser and kieró Airy Sun Stick SPF 50+,
--    with every science claim re-checked against its cited abstract.
-- 2. Adds Joylux's 9 products as separate entries (vFit, vFit PLUS, JUICY LIKE
--    A PEACH, LET'S SPIN, reliefHER, revitalizHER, SHEbar, ILYEO body,
--    coldHER), each with its FDA status verified in the FDA's databases.
-- 3. LOLA pads: removes a user complaint from the safety note (it stays in
--    the community review).
-- 4. ThermaCare and Inito: both were labeled "FDA-cleared". The FDA lists
--    both as Class I devices exempt from clearance; neither has a 510(k).
-- 5. Fixes 11 products filed under the wrong category (e.g. Good Clean Love's
--    vaginal moisturizer was under "supplement").

insert into public.product_catalog (id, name, brand, category, product_type, summary, price, image, url, tags, health_functions, where_to_buy, where_to_buy_in_stock, safety, doctor_opinion, community_review, effectiveness, clinician_opinion_source, clinician_attribution, source, internal, requires_prescription, user_rating, is_active, extra)
values
  ('p-kiero-refining-enzyme-cleanser', 'Refining Enzyme Cleanser', 'kieró', 'skincare', 'physical', 'A powder face cleanser that turns into a creamy foam with water, made with papaya enzymes (papain), beta-glucan, and chia seed extract. kieró positions it as a gentle daily enzyme exfoliant that removes impurities and excess oil without drying and refines skin texture. It is step 1 of kieró''s 5-step routine, which blends Korean-beauty formulation with Latin American botanicals.', '$11.99 for 50 g (1.76 oz)', 'https://us.kieroskincare.com/cdn/shop/files/kiero-_-05_9dcbb676-03a3-45a9-bb4e-ae5dd1708f23.jpg', 'https://us.kieroskincare.com/products/refining-enzyme-cleanser', '["skin","cleanser","exfoliation","vegan","fragrance-free"]'::jsonb, '["skin-hair"]'::jsonb, '["kieró"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Cosmetic face cleanser; not an FDA-cleared drug or medical device. kieró states its products are vegan and cruelty-free and use EWG Green-graded ingredients; ayna did not independently verify those claims.","materials":"Water-activated powder (50 g / 1.76 oz). Cleansing comes mainly from mild synthetic surfactants: sodium cocoyl isethionate, sodium methyl cocoyl taurate, and sodium lauroyl glutamate. It also contains potassium laurate, which is a true soap. The enzyme is papain. Supporting ingredients are allantoin, glycerin, beta-glucan, and chia (Salvia hispanica) seed extract. CI 77499 is black iron oxide, a colorant. No added fragrance, essential oils, or sulfates appear in the published ingredient list.","recalls":"No recalls found.","sideEffects":"Papain is a protein-digesting enzyme and a documented allergen. Published cases include workers who became allergic by breathing it in and a person who reacted to papain in a contact-lens solution; one case report also links papain allergy to kiwi and fig allergy. Anyone allergic to papaya, papain, kiwi, or fig should avoid it or patch test first. The AAD warns that exfoliating while using retinoids or benzoyl peroxide can worsen dryness. Full warnings are listed below.","opinionAlerts":"Allergy note: contains papain (papaya enzyme), a known allergen. Avoid it if you''re allergic to papaya, kiwi, or fig, or patch test first. Benefit claims (refined texture, radiance, barrier support) come from kieró, and no independent clinical study of the finished product was found."}'::jsonb, 'kieró says the papaya enzymes gently exfoliate, beta-glucan hydrates and soothes, and chia seed reinforces the skin barrier, and that the powder foams up to remove oil and impurities without drying. No independent study of this product was found, so what follows is what the research says about its main ingredients.

The main cleansing agent, sodium cocoyl isethionate, is the basis of "syndet" (synthetic detergent) cleansers. Reviews describe syndets as gentler on the skin barrier than soap, and lab work explains why: its micelles are too large to slip into the skin''s outer layer. The formula also contains potassium laurate, which is a true soap, so it isn''t entirely soap-free.

Papain breaks down keratin and other skin proteins in lab tests, which is how enzyme exfoliants work. The evidence is thin, though. A review found only 11 published studies on enzyme exfoliation, with few clinical trials, and concluded that more robust studies are needed before it can be recommended as safe. The lab test took hours to break down skin proteins, and a cleanser is rinsed off within a minute, so any exfoliation is likely mild. Papain is also a documented allergen, mostly in workers who breathe it in. In human skin cells and in mice, it weakened the skin barrier and caused sensitization through the skin.

The supporting ingredients have early evidence, all from leave-on products rather than cleansers. For beta-glucan, a 20-patient split-face trial after laser treatment found that a beta-glucan skin-care regimen improved hydration and redness compared with a placebo cream, and an open-label eczema study of 105 patients found less itch and milder flare-ups. For chia seed oil, a 4% chia oil cream improved hydration and barrier function in an 8-week study of just 10 people, with no control group. Allantoin is recognized by the FDA as an over-the-counter skin protectant at 0.5–2%, but kieró doesn''t list its concentration.

The American Academy of Dermatology advises gentle exfoliation for dry or sensitive skin, moisturizing afterward, and not exfoliating while using retinoids or benzoyl peroxide or on broken or sunburned skin.', 'kieró''s US site shows 251 customer reviews, and 233 of them (93%) are five stars. Most reviews are in Spanish and describe skin feeling very clean, soft, and hydrated, for example: "Muy recomendable, te deja la piel suave e hidratada" ("Highly recommend, it leaves your skin soft and hydrated"). These are reviews on the brand''s own site; no independent review data was found at time of writing.', 'Cleanses with mild syndet surfactants. Papain may add light exfoliation, but enzyme exfoliation has few clinical trials and a cleanser is rinsed off quickly. Evidence for beta-glucan and chia comes from small studies of leave-on products. No independent study of the finished product was found.', 'brand', 'Product claims are sourced from kieró; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"kieró":"https://us.kieroskincare.com/products/refining-enzyme-cleanser"},"ingredients":"Full INCI list per kieró: Zea Mays (Corn) Starch, Sodium Cocoyl Isethionate, Microcrystalline Cellulose, Sodium Methyl Cocoyl Taurate, Potassium Laurate, Sodium Lauroyl Glutamate, Allantoin, Maltodextrin, Papain, Water, CI 77499, Glycerin, Salvia Hispanica Seed Extract, 1,2-Hexanediol, Butylene Glycol, Beta-Glucan, Ethylhexylglycerin.","doctorOpinionShort":"A powder cleanser built on syndet surfactants, which are gentler on the skin barrier than soap, with papaya enzyme (papain) for exfoliation. Evidence for enzyme exfoliation is thin, and the beta-glucan and chia research comes from small studies of leave-on products, not rinse-off cleansers. Papain is a documented allergen, so avoid it if you''re allergic to papaya, kiwi, or fig. No independent study of this product was found.","doctorOpinionCitations":[{"url":"https://us.kieroskincare.com/products/refining-enzyme-cleanser","label":"kieroskincare.com: Refining Enzyme Cleanser — ingredient list and claims"},{"url":"https://www.aad.org/public/everyday-care/skin-care-secrets/routine/safely-exfoliate-at-home","label":"American Academy of Dermatology: How to safely exfoliate at home"}],"whoItsFor":["People who want gentle, daily enzyme exfoliation instead of a scrub or acid","Normal, oily, or combination skin looking for a cleanser that removes excess oil without a tight, stripped feeling","People who prefer a fragrance-free, vegan formula"],"howToUse":{"intro":"Per kieró''s own site: use daily as step 1 (cleanse) of the routine.","steps":["Pour a small amount of powder into wet hands.","Rub your hands together to create a creamy lather, then gently massage it into your skin.","Rinse well and pat your face dry.","Follow with moisturizer. The AAD recommends moisturizing right after any exfoliation."],"sourceUrl":"https://us.kieroskincare.com/products/refining-enzyme-cleanser","sourceLabel":"kieroskincare.com: Refining Enzyme Cleanser"},"warnings":["Allergy to papaya, papain, kiwi, or fig: avoid it or patch test first. Papain is a known allergen.","Using a prescription retinoid, retinol, or benzoyl peroxide: exfoliating on top of them can worsen dryness and irritation (AAD).","Don''t use on broken, cut, or sunburned skin.","Keep out of eyes. If you get redness, burning, or an allergic reaction, stop using it and see a doctor."],"ingredientScience":[{"name":"Papain (papaya enzyme)","text":"kieró states this gently exfoliates. In a lab study, papain broke down keratin and collagen, and on pig skin it had an exfoliating effect, though breakdown took hours. A review (J Cosmet Dermatol, 2022) found only 11 studies on enzyme exfoliation, few of them clinical trials. It concluded that more robust studies are needed before enzyme exfoliation can be recommended as safe. Papain is also an allergen. In human skin cells and in mice it weakened the skin barrier and caused sensitization through the skin. In people, papain allergy is mostly documented in workers who breathe it in, and one case report links it to kiwi and fig allergy.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/34897928/","label":"PubMed: An overview of the use of proteolytic enzymes as exfoliating agents"},{"url":"https://pubmed.ncbi.nlm.nih.gov/35892222/","label":"PubMed: In vitro effect on the proteolytic activity of papain with proteins of the skin as substrate"},{"url":"https://pubmed.ncbi.nlm.nih.gov/25705851/","label":"PubMed: Papain degrades tight junction proteins of human keratinocytes in vitro and sensitizes mice via the skin"},{"url":"https://pubmed.ncbi.nlm.nih.gov/26739411/","label":"PubMed: Papain-induced occupational asthma with kiwi and fig allergy — case report and review of 13 cases"}]},{"name":"Beta-glucan","text":"kieró states this hydrates and soothes. In a split-face, double-blind trial of 20 patients after laser treatment, a beta-glucan skin-care regimen improved hydration and redness compared with a placebo cream. In an open-label study (no blinding or separate control group) of 105 people with mild-to-moderate eczema, a beta-glucan cream reduced itch and eczema severity on the treated side. Both tested leave-on products, not a rinse-off cleanser.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/33128496/","label":"PubMed: Skin care regimens containing β-glucan for skin recovery after fractional laser therapy — split-face, double-blinded, vehicle-controlled study"},{"url":"https://pubmed.ncbi.nlm.nih.gov/26654776/","label":"PubMed: β-Glucan-based cream in supportive treatment of mild-to-moderate atopic dermatitis"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC12023766/","label":"NIH (PMC): Exploring the properties and application potential of β-glucan in skin care"}]},{"name":"Chia seed (Salvia hispanica) extract","text":"kieró states this reinforces the skin barrier. In an 8-week study of 10 people with dry, itchy skin and no control group, a cream with 4% chia seed oil improved skin hydration and barrier function, with no side effects reported. The study was run by a company that makes skin products, and it tested a leave-on oil, not a rinse-off extract.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/20548903/","label":"PubMed: Effectiveness of topical chia seed oil on pruritus of end-stage renal disease patients and healthy volunteers"}]},{"name":"Sodium cocoyl isethionate","text":"The main cleansing agent. Lab research found its micelles are too large to get into the skin''s outer layer, which explains why it is milder than soap or sodium lauryl sulfate. A 2022 review concludes that syndet cleansers like this preserve the skin barrier better than soap.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/17598025/","label":"PubMed: Why is sodium cocoyl isethionate (SCI) mild to the skin barrier?"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8954092/","label":"NIH (PMC): Skin cleansing without or with compromise — soaps and syndets"}]},{"name":"Allantoin","text":"The FDA recognizes allantoin as an over-the-counter skin-protectant ingredient at 0.5–2%. kieró doesn''t list how much this cleanser contains, and in a rinse-off product little stays on the skin.","citations":[{"url":"https://www.ecfr.gov/current/title-21/chapter-I/subchapter-D/part-347/subpart-B/section-347.10","label":"FDA (21 CFR 347.10): Skin protectant active ingredients — allantoin, 0.5 to 2 percent"}]}],"scientificCitations":[{"url":"https://www.aad.org/public/everyday-care/skin-care-secrets/routine/safely-exfoliate-at-home","text":"American Academy of Dermatology: How to safely exfoliate at home","summary":"AAD guidance: people with dry, sensitive, or acne-prone skin should choose gentle exfoliation, moisturize afterward, and avoid exfoliating on broken or sunburned skin or while using retinoids or benzoyl peroxide. This is general guidance, not product-specific validation."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://us.kieroskincare.com/products/refining-enzyme-cleanser","text":"kieroskincare.com: Refining Enzyme Cleanser customer reviews","summary":"kieró''s own product page shows 251 reviews, 93% of them five stars, mostly in Spanish (see the Community summary above)."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-kiero-airy-sun-stick-spf50', 'Airy Sun Stick SPF 50+', 'kieró', 'skincare', 'physical', 'A broad-spectrum SPF 50+ / PA++++ sunscreen stick with chamomile, vitamin E, and madecassoside (from centella). kieró positions it for daily UV protection with a lightweight, non-greasy finish that can be swiped on over makeup, and says it soothes and supports the skin barrier. It uses chemical (organic) UV filters, not zinc or titanium.', '$11.99 for 20 g (0.7 oz)', 'https://us.kieroskincare.com/cdn/shop/files/kiero-_-05_a549ac4a-c417-4be1-8731-03d3c0ffddb8.jpg', 'https://us.kieroskincare.com/products/sun-stick-spf-50', '["skin","spf","sunscreen","vegan"]'::jsonb, '["skin-hair"]'::jsonb, '["kieró"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"In the US, sunscreens are regulated as over-the-counter drugs. kieró doesn''t publish the percentage of each UV filter or say whether the product is water resistant. kieró states its products are vegan and cruelty-free; ayna did not independently verify that.","materials":"Solid silicone-and-wax stick (20 g / 0.7 oz). UV filters: avobenzone (UVA), octocrylene, homosalate, octisalate, and butyloctyl salicylate, all chemical filters with no zinc oxide or titanium dioxide. The soothing ingredients are Roman chamomile flower water, sodium guaiazulene sulfonate (an azulene compound related to chamomile''s blue oil), madecassoside with other centella compounds, panthenol, and vitamin E. Plant oils include sunflower, avocado, soybean, shea, and annatto (Bixa orellana).","recalls":"No recalls found.","sideEffects":"Octocrylene can cause photoallergic reactions (a rash after sun exposure), notably in people who have reacted to ketoprofen, an anti-inflammatory gel. The formula contains Roman chamomile, a daisy-family (Asteraceae) plant; this family is a known contact allergen and cross-reacts with ragweed, so people with those allergies should patch test first. Full warnings are listed below.","opinionAlerts":"Safety note: sunscreen only reaches its labeled SPF when applied generously, and most people apply far less, so go over each area several times. Its chemical UV filters were absorbed into the bloodstream in an FDA study; the FDA researchers said that doesn''t mean people should stop using sunscreen. Contains Roman chamomile, so patch test if you''re allergic to ragweed or daisies. Soothing and barrier claims come from kieró, and no independent study of the finished product was found."}'::jsonb, 'kieró says the chamomile soothes, the vitamin E gives antioxidant defense, and the madecassoside strengthens the skin barrier, and that the stick can be swiped on over makeup. No independent study of this product was found, so what follows is what the research says about daily sunscreen and its ingredients.

The strongest evidence is for daily sunscreen use itself, from a randomized trial of 1,621 adults in Nambour, Australia, using an SPF 15+ sunscreen. People assigned to daily use had 24% less skin aging over 4.5 years than people who used sunscreen when they chose to. They also had about 39% fewer squamous cell carcinoma tumors, though the share of people who got one didn''t differ significantly, and there was no effect on basal cell carcinoma. Ten years later, the daily group had 11 new melanomas versus 22, a difference just short of statistical significance overall, though the drop in invasive melanoma (3 vs 11) was significant.

How much you apply matters. SPF is tested at 2 mg/cm², while consumers typically apply 0.5–1 mg/cm², and lab studies show actual SPF drops steeply at those amounts. One study found SPF 30–50 products may not give enough protection at typical consumer amounts. The AAD and FDA advise applying 15 minutes before sun exposure and reapplying at least every two hours, and more often when swimming or sweating. kieró doesn''t claim water resistance.

The UV filters in this stick (avobenzone, octocrylene, homosalate, octisalate) were all absorbed into the bloodstream in a 2020 FDA randomized trial of 48 people. Levels were above the point at which the FDA can waive further safety testing, and the FDA researchers said this does not mean people should stop using sunscreen. A separate lab study found benzophenone, which it calls a possible human carcinogen, in all 28 octocrylene-containing products tested, increasing with age and heat. People who want to avoid these filters can choose a mineral (zinc oxide) sunscreen.

For the soothing ingredients, a 6-month double-blind study of 20 women found that a cream combining 5% vitamin C with 0.1% madecassoside improved wrinkles, firmness, and hydration. Because the two were combined, the result can''t be credited to madecassoside alone. In a separate study, madecassoside reduced UV-triggered inflammation in skin cells and reduced UV tanning on human skin over 8 weeks. Vitamin E is the main antioxidant naturally found in skin.', 'kieró''s US site shows 657 customer reviews, and 593 of them (90%) are five stars; the rest are four stars. Most reviews are in Spanish and praise how easily it goes on, how fast it absorbs, and its non-greasy feel, including over makeup. For example: "No es grasoso y protege muy bien tu piel del sol" ("It''s not greasy and protects your skin from the sun really well"). These are reviews on the brand''s own site; no independent review data was found at time of writing.', 'Labeled SPF 50+ / PA++++ broad spectrum, but real-world protection depends on how much you apply. Daily sunscreen use slowed skin aging and reduced squamous cell carcinoma tumors in a randomized trial. No independent study of the finished product was found.', 'brand', 'Product claims are sourced from kieró; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"kieró":"https://us.kieroskincare.com/products/sun-stick-spf-50"},"ingredients":"Full INCI list per kieró: Dimethicone, Synthetic Wax, Vinyl Dimethicone/Methicone Silsesquioxane Crosspolymer, Cetyl Ethylhexanoate, Octocrylene, Homosalate, Methyl Methacrylate Crosspolymer, Dibutyl Adipate, Butyloctyl Salicylate, Octisalate, Avobenzone, Pentylene Glycol, Polyglyceryl-4 Oleate, Helianthus Annuus (Sunflower) Seed Oil, Polyglyceryl-6 Oleate, Polyhydroxystearic Acid, Methylpropanediol, Persea Gratissima (Avocado) Oil, Ethylhexylglycerin, Caprylyl Glycol, Glycine Soja (Soybean) Oil, Tocopherol, Steareth-30, Lactobacillus Ferment Lysate, Butyrospermum Parkii (Shea) Butter Extract, Bixa Orellana Seed Oil, Water, Sodium Guaiazulene Sulfonate, Panthenol, Butylene Glycol, 1,2-Hexanediol, Anthemis Nobilis Flower Water, Madecassoside, Asiaticoside, Asiatic Acid, Madecassic Acid.","doctorOpinionShort":"Daily sunscreen use slowed skin aging and reduced squamous cell carcinoma tumors in a large randomized trial, with a likely drop in invasive melanoma. Protection depends on applying enough, so go over each area several times and reapply every two hours. Its chemical filters are absorbed into the blood; the FDA researchers said that doesn''t mean people should stop using sunscreen, and mineral sunscreen is an alternative. No independent study of this product was found.","doctorOpinionCitations":[{"url":"https://us.kieroskincare.com/products/sun-stick-spf-50","label":"kieroskincare.com: Airy Sun Stick SPF 50+ — ingredient list and claims"},{"url":"https://www.aad.org/public/everyday-care/sun-protection/shade-clothing-sunscreen/how-to-apply-sunscreen","label":"American Academy of Dermatology: How to apply sunscreen"},{"url":"https://www.fda.gov/drugs/understanding-over-counter-medicines/sunscreen-how-help-protect-your-skin-sun","label":"FDA: Sunscreen — how to help protect your skin from the sun"}],"whoItsFor":["People who want a mess-free daily SPF they can reapply over makeup","Oily or combination skin looking for a non-greasy finish","Touch-ups on the face, ears, nose, and around the eyes during the day"],"howToUse":{"intro":"Per kieró''s own site: swipe the stick on as the last step of your morning routine, or over makeup, evenly covering all sun-exposed areas. Reapply through the day as needed.","steps":["Go over each area several times (back and forth). A single light swipe won''t deliver the labeled SPF.","Apply about 15 minutes before going outside (AAD).","Reapply at least every two hours, and right after swimming or sweating (AAD / FDA)."],"sourceUrl":"https://us.kieroskincare.com/products/sun-stick-spf-50","sourceLabel":"kieroskincare.com: Airy Sun Stick SPF 50+"},"warnings":["Allergy to ragweed, chamomile, or other daisy-family plants: patch test first.","Have you reacted to ketoprofen (an anti-inflammatory gel)? Octocrylene can cause photoallergic reactions in people sensitized to it.","Rash or irritation, especially after sun exposure: stop using it and see a doctor.","Not stated as water resistant: reapply after swimming or sweating.","Infants under 6 months: the FDA doesn''t recommend sunscreen; keep them out of the sun instead."],"ingredientScience":[{"name":"Daily broad-spectrum sunscreen","text":"In the Nambour randomized trial (1,621 adults, SPF 15+), people assigned to daily sunscreen showed no detectable increase in skin aging over 4.5 years, 24% less aging than the discretionary-use group. They had 39% fewer squamous cell carcinoma tumors, though the share of people who got one didn''t differ significantly, and there was no effect on basal cell carcinoma. Ten years later, the daily group had 11 new melanomas vs 22; that overall difference was just short of statistical significance (p = 0.051), while the drop in invasive melanoma (3 vs 11) was significant.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/10475183/","label":"PubMed: Daily sunscreen application in prevention of basal-cell and squamous-cell carcinomas — a randomised controlled trial (Green et al., Lancet 1999)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/23732711/","label":"PubMed: Sunscreen and prevention of skin aging — a randomized trial (Hughes et al., Ann Intern Med 2013)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/21135266/","label":"PubMed: Reduced melanoma after regular sunscreen use — randomized trial follow-up (Green et al., J Clin Oncol 2011)"}]},{"name":"How much you apply","text":"SPF is measured at 2 mg/cm², but consumers typically apply 0.5–1 mg/cm². Lab studies on volunteers found actual SPF falls significantly at lower amounts. One found SPF 30–50 products may not give enough protection at typical consumer amounts.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/19614894/","label":"PubMed: The influence of the amount of sunscreen applied on its sun protection factor"},{"url":"https://pubmed.ncbi.nlm.nih.gov/22463921/","label":"PubMed: High-SPF sunscreens may compensate for lower user application amounts"}]},{"name":"Chemical UV filters (avobenzone, octocrylene, homosalate, octisalate)","text":"In a 2020 FDA randomized trial of 48 people, all of these filters were absorbed into the bloodstream after a single application, above the level at which the FDA can waive further safety testing. The researchers concluded this does not mean people should stop using sunscreen. A separate lab study found benzophenone, a possible human carcinogen, in all 28 octocrylene-containing products tested. Levels rose with time and heat.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31961417/","label":"PubMed: Effect of sunscreen application on plasma concentration of sunscreen active ingredients — a randomized clinical trial (JAMA 2020)"},{"url":"https://pubmed.ncbi.nlm.nih.gov/33763894/","label":"PubMed: The presence of benzophenone in sunscreens and cosmetics containing the organic UV filter octocrylene"}]},{"name":"Madecassoside (centella)","text":"kieró states this strengthens the skin barrier. No study testing madecassoside alone for barrier strength was found. In a 6-month double-blind study of 20 women, a cream combining 5% vitamin C with 0.1% madecassoside improved wrinkles, firmness, and hydration, but the result can''t be credited to madecassoside alone. In another study, madecassoside reduced UV-triggered inflammation in skin cells and reduced UV tanning on human skin over 8 weeks.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/18503551/","label":"PubMed: Long-term effects of topical ascorbic acid and madecassoside in photoaged human skin"},{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC6290557/","label":"NIH (PMC): Madecassoside inhibits melanin synthesis by blocking ultraviolet-induced inflammation"}]},{"name":"Roman chamomile","text":"kieró states this soothes sensitive skin. No study of chamomile flower water for soothing was found. Chamomile is in the daisy (Asteraceae) family, whose compounds are known skin sensitizers that can cross-react with ragweed.","citations":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC11847717/","label":"NIH (PMC): Allergic potential of medicinal plants from the Asteraceae family (2025 review)"}]},{"name":"Vitamin E","text":"kieró states this gives antioxidant defense. Vitamin E is the main antioxidant naturally found in human skin, and UV exposure depletes it.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/12239421/","label":"PubMed: Antioxidants and the Response of Skin to Oxidative Stress — Vitamin E as a Key Indicator"}]}],"scientificCitations":[{"url":"https://www.aad.org/public/everyday-care/sun-protection/shade-clothing-sunscreen/how-to-apply-sunscreen","text":"American Academy of Dermatology: How to apply sunscreen","summary":"AAD guidance: use SPF 30+ broad-spectrum sunscreen, apply about 15 minutes before going out, and reapply every two hours and after swimming or sweating. This is general guidance, not product-specific validation."},{"url":"https://www.fda.gov/drugs/understanding-over-counter-medicines/sunscreen-how-help-protect-your-skin-sun","text":"FDA: Sunscreen — how to help protect your skin from the sun","summary":"FDA guidance: use broad-spectrum SPF 15+, apply 15 minutes before sun exposure, reapply at least every two hours, and keep infants under 6 months out of the sun rather than using sunscreen."}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[{"platform":"website","url":"https://us.kieroskincare.com/products/sun-stick-spf-50","text":"kieroskincare.com: Airy Sun Stick SPF 50+ customer reviews","summary":"kieró''s own product page shows 657 reviews, 90% of them five stars and the rest four stars, mostly in Spanish (see the Community summary above)."}]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-joylux-vfit', 'vFit® Device', 'Joylux', 'intimate-care', 'physical', 'An at-home intimate wellness device that you insert into the vagina. It combines red light (six 662 nm LEDs), gentle heat, and vibration in sessions of 6 to 10 minutes. Joylux markets it to midlife women for more natural lubrication, sensation, and confidence, and says it supports pelvic floor strength.', '$395', 'https://cdn.shopify.com/s/files/1/1120/5174/files/vfit-plus-upgraded-device-259789.jpg?v=1745343867', 'https://joylux.com/products/vfit', '["menopause","discomfort"]'::jsonb, '["vaginal-health"]'::jsonb, '["Joylux"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not FDA-cleared or approved. Joylux says the FDA designated vFit a \"low-risk general wellness device\" in 2017. That category isn''t reviewed for safety or effectiveness and can''t claim to treat any condition, including dryness, incontinence, or pelvic floor problems.","materials":"Rechargeable insertable device with six 662 nm red LEDs, heat, and vibration modes. Comes with a USB charging cable and power cube, a storage pouch, and a user guide, per Joylux.","recalls":"No recalls found.","sideEffects":"In the Joylux-funded 2017 study, 2 of 55 women (3.6%) had an adverse event: one urinary tract infection and one case of discomfort from too much warmth. Joylux''s product page lists no contraindications, so check with your doctor first if you are pregnant, have an IUD or implanted device, or have a vaginal infection or unexplained bleeding.","opinionAlerts":"This is a general wellness device, not an FDA-cleared treatment. The only published study was funded by Joylux, run by its consultants, and had no control group."}'::jsonb, 'Joylux says vFit is Ob-Gyn designed, supports pelvic floor strength, and that users report more natural lubrication, more sensation, and more confidence.

The main published evidence, which Joylux cites, is a 2017 study in the International Urogynecology Journal of "multimodal vaginal toning" therapy. 55 women with stress urinary incontinence after childbirth did 24 ten-minute sessions at home over 50 days. Among the 48 who finished, leakage on a pad test and symptom and quality-of-life scores improved substantially. The study had no control group, so it can''t separate the device''s effect from placebo or the passage of time. Joylux funded it, and both authors were Joylux consultants.

A 2019 review co-written by Joylux''s chief medical officer argued that red-light therapy (photobiomodulation) is a plausible approach for vaginal symptoms of menopause, calling the evidence preliminary. It was not a trial of vFit.

The FDA classes vFit as a general wellness product, so it hasn''t been reviewed as a treatment. For bothersome dryness, pain with sex, or bladder leaks, talk to a doctor or a pelvic floor physical therapist.', null, null, 'brand', 'Product claims are Joylux''s. The study it cites was funded by Joylux and written by Joylux consultants, one of whom is Joylux''s chief medical officer.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Joylux":"https://joylux.com/products/vfit"},"doctorOpinionShort":"A red-light, heat, and vibration device sold for intimate wellness. It is an FDA \"general wellness\" product, not FDA-cleared. One Joylux-funded study with no control group reported less leakage in 48 women with postpartum stress incontinence.","doctorOpinionCitations":[{"url":"https://joylux.com/blogs/faq/are-vfit-or-vfit-plus-products-fda-approved","label":"Joylux FAQ: Are vFit or vFit PLUS products FDA approved?"}],"whoItsFor":["Midlife women curious about an at-home, drug-free wellness device for intimate comfort, who understand it is not an FDA-cleared treatment"],"howToUse":{"intro":"Per Joylux''s product page:","steps":["Use every other day, starting with 6-minute sessions and working up to 8, then 10 minutes.","For the first 60 days use it 3 times a week, then 1 to 2 times a week to maintain.","Joylux recommends a clear, water-based gel to help with insertion."],"sourceUrl":"https://joylux.com/products/vfit","sourceLabel":"joylux.com: vFit Device"},"warnings":["Not an FDA-cleared treatment for dryness, incontinence, or pelvic floor problems.","Joylux lists no contraindications on the product page. Check with a doctor first if you are pregnant, have an IUD or implanted device, have a vaginal infection, or have unexplained bleeding.","Stop if it causes pain, burning, or too much warmth."],"ingredientScience":[{"name":"The study behind vFit","text":"A 2017 single-group study (no control group) of 55 women with postpartum stress urinary incontinence. They did 24 ten-minute home sessions over 50 days. Of the 38 who had measurable leakage at the start, 84% had more than 50% less leakage on a pad test, and among the 48 who finished, symptom and quality-of-life scores improved. Joylux funded the study, and both authors were Joylux consultants.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/28035444/","label":"PubMed: Multimodal vaginal toning for bladder symptoms and quality of life in stress urinary incontinence (Int Urogynecol J, 2017)"}]},{"name":"Red light (photobiomodulation)","text":"A 2019 review argued red-light therapy may help vaginal symptoms of menopause, calling the evidence preliminary. Its authors include Joylux''s chief medical officer and a Joylux consultant. It is a review, not a trial of vFit.","citations":[{"url":"https://pubmed.ncbi.nlm.nih.gov/31210575/","label":"PubMed: The rationale for photobiomodulation therapy of vaginal tissue for genitourinary syndrome of menopause (2019 review)"}]}],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-joylux-vfit-plus', 'vFit® PLUS', 'Joylux', 'intimate-care', 'physical', 'The same red-light, heat, and vibration intimate wellness device as vFit, with the PLUS upgrade included: brighter LEDs, a 12-minute session option, and 4 more vibration modes, per Joylux.', '$494', 'https://cdn.shopify.com/s/files/1/1120/5174/files/vfit-plus-upgraded-device-259789.jpg?v=1745343867', 'https://joylux.com/products/vfit-plus', '["menopause","discomfort"]'::jsonb, '["vaginal-health"]'::jsonb, '["Joylux"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not FDA-cleared or approved. Joylux says the FDA designated vFit and vFit PLUS \"low-risk general wellness devices\" in 2017. That category isn''t reviewed for safety or effectiveness and can''t claim to treat any condition.","materials":"Rechargeable insertable device with red LEDs, heat, and vibration, per Joylux.","recalls":"No recalls found.","sideEffects":"Same device as vFit with stronger settings. See the vFit entry: in the Joylux-funded study, 2 of 55 women had an adverse event (one urinary tract infection, one too much warmth).","opinionAlerts":"This is a general wellness device, not an FDA-cleared treatment. The only published study was funded by Joylux and had no control group."}'::jsonb, 'vFit PLUS is the vFit device with brighter LEDs, a longer session option, and more vibration modes. No study comparing PLUS with the standard vFit was found. The evidence is the same as for vFit: one Joylux-funded study of 55 women with postpartum stress incontinence, with no control group. See the vFit entry for details.', null, null, 'brand', 'Product claims are Joylux''s; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Joylux":"https://joylux.com/products/vfit-plus"},"doctorOpinionShort":"vFit with stronger settings. An FDA \"general wellness\" product, not FDA-cleared. No study compares it with the standard vFit.","doctorOpinionCitations":[{"url":"https://joylux.com/blogs/faq/are-vfit-or-vfit-plus-products-fda-approved","label":"Joylux FAQ: Are vFit or vFit PLUS products FDA approved?"},{"url":"https://pubmed.ncbi.nlm.nih.gov/28035444/","label":"PubMed: Multimodal vaginal toning for bladder symptoms and quality of life in stress urinary incontinence (Int Urogynecol J, 2017)"}],"warnings":["Not an FDA-cleared treatment for dryness, incontinence, or pelvic floor problems.","Check with a doctor first if you are pregnant, have an IUD or implanted device, have a vaginal infection, or have unexplained bleeding."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-joylux-juicy-like-a-peach', 'JUICY LIKE A PEACH® Vaginal Gel', 'Joylux', 'intimate-care', 'physical', 'A hormone-free vaginal gel (pH 3.8) applied inside the vagina once a day with an applicator. Joylux markets it for menopausal dryness and pain during sex, saying it forms a moisture barrier on vaginal tissue.', '$59 for 30 applications', 'https://cdn.shopify.com/s/files/1/1120/5174/files/juicy-like-a-peach-3736266.jpg?v=1781733740', 'https://joylux.com/products/juicy-like-a-peach', '["menopause","discomfort","hormone-free"]'::jsonb, '["vaginal-health","sexual-health"]'::jsonb, '["Joylux"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"FDA-cleared as a personal lubricant (Class II). Joylux''s FDA listing for this gel cites 510(k) K200098, a clearance held by Peptonic Medical for its VagiVital Aktivgel. A personal-lubricant clearance covers lubrication and moisture; it is not an FDA approval to treat menopause.","materials":"36 g tube with an applicator, 30 pre-measured 1 mL doses, per Joylux.","recalls":"No recalls found.","sideEffects":"Per Joylux: possible mild, short-lived itching, irritation, burning, or discharge; rarely severe irritation or urinary tract infection. Stop and see a doctor if symptoms persist.","opinionAlerts":"Not compatible with natural rubber latex or polyurethane condoms, per Joylux. It is only compatible with polyisoprene condoms."}'::jsonb, 'Joylux says the gel relieves vaginal dryness and pain during sex and that comfort builds with daily use. It calls the product "clinically studied," but its page doesn''t name or link a study, and ayna didn''t find one for this product. Its FDA clearance is as a personal lubricant. If dryness or pain persists, talk to a doctor.', null, null, 'brand', 'Product claims are Joylux''s; regulatory status verified in the FDA 510(k) and registration databases.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Joylux":"https://joylux.com/products/juicy-like-a-peach"},"ingredients":"Purified water, hypromellose, benzoic acid, lactic acid, sodium hydroxide, per Joylux.","doctorOpinionShort":"A hormone-free vaginal gel, FDA-cleared as a personal lubricant. Joylux markets it for menopausal dryness and pain with sex but doesn''t cite a study. Not compatible with latex condoms.","doctorOpinionCitations":[{"url":"https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpmn/pmn.cfm?ID=K200098","label":"FDA 510(k) K200098: VagiVital Aktivgel (Peptonic Medical), personal lubricant, cleared 2020"}],"howToUse":{"intro":"Per Joylux''s product page:","steps":["Use once a day, preferably before bed.","Attach the applicator, fill it to 1 mL, insert gently, and press the plunger.","Rinse the applicator with warm water and antibacterial soap after each use."],"sourceUrl":"https://joylux.com/products/juicy-like-a-peach","sourceLabel":"joylux.com: JUICY LIKE A PEACH"},"warnings":["Not compatible with natural rubber latex or polyurethane condoms.","Stop and see a doctor if itching, burning, or irritation persists."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-joylux-lets-spin', 'LET''S SPIN® Intimacy Gel', 'Joylux', 'sex-tech', 'physical', 'A water-based intimacy gel with hyaluronic acid and aloe, made with Respin (Halle Berry''s brand). Joylux markets it to moisturize, supplement natural lubrication, and make sex more comfortable when dryness or hormonal changes get in the way.', '$45 for 60 mL', 'https://cdn.shopify.com/s/files/1/1120/5174/files/lets-spin-intimacy-gel-422294.jpg?v=1727172815', 'https://joylux.com/products/lets-spin-intimacy-gel', '["menopause","discomfort","hormone-free"]'::jsonb, '["sexual-health","vaginal-health"]'::jsonb, '["Joylux"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"FDA-cleared as a personal lubricant (Class II): 510(k) K242958, \"Joylux Intimacy Gel,\" cleared March 20, 2025. Joylux''s FDA listing names it as LET''S SPIN.","materials":"60 mL pump bottle (a mini tube is also sold), pH 4.0–5.0, per Joylux.","recalls":"No recalls found.","sideEffects":"Stop if irritation develops.","opinionAlerts":"Compatible with natural rubber latex and polyisoprene condoms, but not polyurethane condoms, per Joylux."}'::jsonb, 'This is an FDA-cleared, water-based personal lubricant. Joylux also calls it "clinically proven," but its page doesn''t name or link a study.', null, null, 'brand', 'Product claims are Joylux''s; regulatory status verified in the FDA 510(k) database.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Joylux":"https://joylux.com/products/lets-spin-intimacy-gel"},"ingredients":"Water (Aqua), Sodium Hyaluronate, Propanediol, Hydroxyethylcellulose, Xanthan Gum, Sodium Hydroxide, Sodium Benzoate, Potassium Sorbate, Citric Acid, Aloe Vera 200X Powder, Gluconolactone, per Joylux.","doctorOpinionShort":"A water-based lubricant with hyaluronic acid and aloe, FDA-cleared as a personal lubricant (K242958). Latex-condom compatible.","doctorOpinionCitations":[{"url":"https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpmn/pmn.cfm?ID=K242958","label":"FDA 510(k) K242958: Joylux Intimacy Gel (PG3100), personal lubricant, cleared 2025"}],"howToUse":{"intro":"Per Joylux''s product page: apply as much as you like to intimate areas and reapply as often as needed. Store at room temperature.","steps":[],"sourceUrl":"https://joylux.com/products/lets-spin-intimacy-gel","sourceLabel":"joylux.com: LET''S SPIN Intimacy Gel"},"warnings":["Not compatible with polyurethane condoms."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-joylux-reliefher', 'reliefHER™ Vaginal Hydration Melts', 'Joylux', 'intimate-care', 'physical', 'Non-hormonal vaginal melts made with coconut oil, cocoa butter, vitamin E, and hyaluronic acid (15 mg per melt, per Joylux). You insert one at bedtime every 2 to 3 days for vaginal hydration.', '$49 for 10 melts', 'https://cdn.shopify.com/s/files/1/1120/5174/files/reliefHER_10pack_HERO.jpg?v=1782326170', 'https://joylux.com/products/reliefher', '["menopause","discomfort","hormone-free"]'::jsonb, '["vaginal-health"]'::jsonb, '["Joylux"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not listed with the FDA as a medical device (checked 2026-10-02); sold as a personal-care product.","materials":"Solid melts that dissolve at body temperature. Store somewhere cool.","recalls":"No recalls found.","sideEffects":"Per Joylux: stop if irritation develops. Check with a doctor first if you have a vaginal infection, unusual bleeding, a recent procedure or childbirth, open sores, or an allergy to any ingredient.","opinionAlerts":"Contains coconut oil and cocoa butter. The CDC warns that oil-based products can cause condoms to break, and Joylux''s page doesn''t address condom compatibility."}'::jsonb, 'Joylux describes these as hyaluronic-acid melts for vaginal hydration, "backed by science," but doesn''t name or link a study for this product, and ayna didn''t find one.', null, null, 'brand', 'Product claims are Joylux''s; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Joylux":"https://joylux.com/products/reliefher"},"ingredients":"Coconut Oil, Vitamin E, Hyaluronic Acid, Silica, Cocoa Butter, per Joylux.","doctorOpinionShort":"Oil-based vaginal melts with hyaluronic acid. Not an FDA-listed medical device. No product-specific study found.","doctorOpinionCitations":[{"url":"https://www.cdc.gov/condom-use/resources/external.html","label":"CDC: How to use an external condom (oil-based products can cause condoms to break)"}],"howToUse":{"intro":"Per Joylux''s product page:","steps":["Wash your hands, then insert 1 melt into the vagina, as deep as is comfortable, preferably at bedtime.","Use every 2 to 3 days, or as needed.","Store in a cool place; a chilled melt stays firm."],"sourceUrl":"https://joylux.com/products/reliefher","sourceLabel":"joylux.com: reliefHER Vaginal Hydration Melts"},"warnings":["Vaginal infection, unusual bleeding, recent procedure or childbirth, or open sores: check with a doctor first.","Contains oils; the CDC warns oil-based products can cause condoms to break."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-joylux-revitalizher', 'revitalizHER™ Hydrating Serum', 'Joylux', 'intimate-care', 'physical', 'An oil-based serum for the external vulva, made with coconut, sea buckthorn, and jojoba oils plus beeswax, vitamin E, vitamin C, and mandarin orange peel oil. Joylux markets it to shield against dryness.', '$49 for 30 mL', 'https://cdn.shopify.com/s/files/1/1120/5174/files/revitalizher-hydrating-serum-987054.jpg?v=1742591593', 'https://joylux.com/products/revitalizher', '["menopause","discomfort"]'::jsonb, '["vaginal-health"]'::jsonb, '["Joylux"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Not listed with the FDA as a medical device (checked 2026-10-02); sold as a cosmetic.","materials":"30 mL serum.","recalls":"No recalls found.","sideEffects":"For external use on the vulva only. Do not use internally, per Joylux. It contains mandarin orange peel oil.","opinionAlerts":"External use only, per Joylux."}'::jsonb, 'An oil-based external moisturizer. Joylux doesn''t cite a study for this product, and ayna didn''t find one.', null, null, 'brand', 'Product claims are Joylux''s; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Joylux":"https://joylux.com/products/revitalizher"},"ingredients":"Caprylic/Capric Triglyceride, Cocos Nucifera (Coconut) Oil, Hippophae Rhamnoides (Sea Buckthorn) Oil, Beeswax, Simmondsia Chinensis (Jojoba) Oil, Tocopherol (Vitamin E), Tetrahexyldecyl Ascorbate (Vitamin C), Citrus Nobilis (Mandarin Orange) Peel Oil, per Joylux.","doctorOpinionShort":"An external vulvar oil serum. Cosmetic, not FDA-listed. No product-specific study found.","howToUse":{"intro":"Per Joylux''s product page: after cleansing, pat dry and apply to the external vulva. Don''t rinse. Don''t use internally.","steps":[],"sourceUrl":"https://joylux.com/products/revitalizher","sourceLabel":"joylux.com: revitalizHER Hydrating Serum"},"warnings":["External use only.","Stop if it stings or irritates."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-joylux-shebar', 'SHEbar® Intimate Cleansing Bar', 'Joylux', 'intimate-care', 'physical', 'A soap-free cleansing bar for intimate areas (pH about 4.5, per Joylux) with coconut, argan, and avocado oils. It contains added fragrance.', '$13 for 3.2 oz', 'https://cdn.shopify.com/s/files/1/1120/5174/files/SHEbar_Packshot_2.jpg?v=1778785371', 'https://joylux.com/products/shebar', '["comfort"]'::jsonb, '["vaginal-health"]'::jsonb, '["Joylux"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"Cosmetic cleanser; not an FDA-regulated medical device.","materials":"3.2 oz (90.7 g) bar.","recalls":"No recalls found.","sideEffects":"Contains added fragrance. Stop if it causes itching or burning.","opinionAlerts":"Contains added fragrance."}'::jsonb, 'A soap-free bar built on sodium cocoyl isethionate, a syndet surfactant; reviews describe syndets as gentler on the skin barrier than soap. It does contain added fragrance. Joylux doesn''t cite a study for this product.', null, null, 'brand', 'Product claims are Joylux''s; no independent clinician endorsement verified by ayna.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Joylux":"https://joylux.com/products/shebar"},"ingredients":"Sodium Cocoyl Isethionate, Hydrogenated Vegetable Oil, Polyglyceryl-4 Laurate, Water, Glycerin, Fragrance, Titanium Dioxide (CI 77891), Cocos Nucifera (Coconut) Oil, Argania Spinosa Kernel Oil, Persea Gratissima (Avocado) Oil, Tetrasodium Glutamate Diacetate, per Joylux.","doctorOpinionShort":"A mild, soap-free bar, but it contains added fragrance.","doctorOpinionCitations":[{"url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC8954092/","label":"NIH (PMC): Skin cleansing without or with compromise — soaps and syndets (2022 review)"}],"warnings":["Contains fragrance; stop if it causes itching or burning."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-joylux-ilyeo-body', 'ILYEO™ body', 'Joylux', 'pain-relief', 'physical', 'A flexible, cordless silicone wrap that combines red light, heat, and vibration for muscle and joint pain. Joylux markets it to midlife women; it is used for 10-minute sessions on areas like the shoulders or knees. Listed as a pre-order shipping the week of October 5 at time of writing.', '$199', 'https://cdn.shopify.com/s/files/1/1120/5174/files/ilyeo-body-8041504.jpg?v=1789522687', 'https://joylux.com/products/ilyeo-body', '["menopause","discomfort"]'::jsonb, '["comfort"]'::jsonb, '["Joylux"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"FDA-registered Class II therapeutic infrared heating lamp, exempt from 510(k) premarket review. Verified in the FDA device registration database (2026-10-02); Joylux''s page says the same.","materials":"Flexible medical-grade silicone wrap with red light, heat, and vibration, per Joylux.","recalls":"No recalls found.","sideEffects":"Per Joylux: don''t use if you take medications or products that increase light sensitivity, have impaired sensation in the area, or have active skin cancer or suspicious lesions. Ask your doctor first if you are pregnant or have a history of skin cancer. On darker skin tones, start with 2-minute sessions and work up to 10.","opinionAlerts":"Exempt devices like this aren''t reviewed by the FDA for effectiveness. Joylux calls it \"clinically proven\" but doesn''t name a study."}'::jsonb, 'Joylux says ILYEO body is indicated for temporary relief of minor muscle and joint pain, arthritis pain and stiffness, and muscle spasms, and to temporarily increase local blood circulation. It is registered with the FDA but exempt from premarket review, so the FDA hasn''t evaluated its effectiveness. Joylux calls it "clinically proven" without naming a study, and ayna didn''t find one for this device.', null, null, 'brand', 'Product claims are Joylux''s; regulatory status verified in the FDA registration database.', 'curated', false, false, null, true, '{"fsaHsaEligible":true,"whereToBuyLinks":{"Joylux":"https://joylux.com/products/ilyeo-body"},"doctorOpinionShort":"A red-light, heat, and vibration wrap for minor muscle and joint pain. FDA-registered Class II and exempt from review; no product-specific study found.","howToUse":{"intro":"Per Joylux''s product page: 10-minute sessions, daily or as needed, following the protocol in the ILYEO app for the area being treated.","steps":["On darker skin tones, start with 2-minute sessions and gradually increase to 10."],"sourceUrl":"https://joylux.com/products/ilyeo-body","sourceLabel":"joylux.com: ILYEO body"},"warnings":["Don''t use if you take light-sensitizing medications or products, have impaired sensation in the area, or have active skin cancer or suspicious lesions.","Pregnant, or a history of skin cancer: ask your doctor first."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb),
  ('p-joylux-coldher', 'coldHER™ Cooling Bra Inserts', 'Joylux', 'menopause', 'physical', 'Reusable cooling pads made with phase-change material, which absorbs body heat as it melts. You tuck them into your bra for hot flashes, breast or nipple soreness, or cooling down after exercise. They re-harden at room temperature in about 30 minutes, or faster in the fridge.', '$21 for 2 pads', 'https://cdn.shopify.com/s/files/1/1120/5174/files/coldher-cooling-bra-inserts-9258458.jpg?v=1753846926', 'https://joylux.com/products/coldher', '["menopause","comfort"]'::jsonb, '["perimenopause"]'::jsonb, '["Joylux"]'::jsonb, '{}'::jsonb, '{"fdaStatus":"FDA-registered Class I reusable hot/cold pack, exempt from premarket review (verified in the FDA device registration database, 2026-10-02). Joylux sells it as a general wellness product.","materials":"Two pads of phase-change material, per Joylux.","recalls":"No recalls found.","sideEffects":"Stop if your skin becomes irritated. Wipe clean with a damp cloth and mild soap.","opinionAlerts":"Gives temporary cooling comfort; it doesn''t treat the cause of hot flashes."}'::jsonb, 'A simple reusable cooling pad for temporary comfort during hot flashes or breast soreness. If hot flashes are frequent or disrupt your sleep, talk to a doctor about treatments that reduce them.', null, null, 'brand', 'Product claims are Joylux''s; regulatory status verified in the FDA registration database.', 'curated', false, false, null, true, '{"whereToBuyLinks":{"Joylux":"https://joylux.com/products/coldher"},"doctorOpinionShort":"Reusable cooling pads for temporary relief during hot flashes or breast soreness. FDA-registered Class I.","howToUse":{"intro":"Per Joylux''s product page:","steps":["Tuck the pads into your bra strap with the cooling material against your skin, at the top of the breasts, under the arms, or wherever you need it.","For nipple soreness, place a pad directly over the nipple.","Re-cool at room temperature (about 30 minutes) or in the fridge."],"sourceUrl":"https://joylux.com/products/coldher","sourceLabel":"joylux.com: coldHER Cooling Bra Inserts"},"warnings":["Stop if your skin becomes irritated."],"verificationLinks":{"doctor":{"links":[]},"scientific":{"links":[]},"community":{"links":[]}},"integrations":[],"badges":[],"isEmergingBrand":true}'::jsonb)
on conflict (id) do update set
    name = excluded.name,
    brand = excluded.brand,
    category = excluded.category,
    product_type = excluded.product_type,
    summary = excluded.summary,
    price = excluded.price,
    image = excluded.image,
    url = excluded.url,
    tags = excluded.tags,
    health_functions = excluded.health_functions,
    where_to_buy = excluded.where_to_buy,
    where_to_buy_in_stock = excluded.where_to_buy_in_stock,
    safety = excluded.safety,
    doctor_opinion = excluded.doctor_opinion,
    community_review = excluded.community_review,
    effectiveness = excluded.effectiveness,
    clinician_opinion_source = excluded.clinician_opinion_source,
    clinician_attribution = excluded.clinician_attribution,
    source = excluded.source,
    internal = excluded.internal,
    requires_prescription = excluded.requires_prescription,
    user_rating = excluded.user_rating,
    is_active = excluded.is_active,
    extra = excluded.extra;

update public.product_catalog
set safety = safety - 'opinionAlerts'
where id = 'p-lola-pad';

update public.product_catalog
set safety = jsonb_set(safety, '{fdaStatus}', to_jsonb('FDA-listed Class I medical device (disposable heat pack), which is exempt from FDA premarket clearance; not FDA-cleared. Verified in the FDA device registration database, 2026-10-02.'::text))
where id = 'p-thermacare';

update public.product_catalog
set safety = jsonb_set(safety, '{fdaStatus}', to_jsonb('FDA-listed Class I over-the-counter hormone test, which is exempt from FDA premarket clearance; no 510(k) clearance found. Verified in the FDA device registration database, 2026-10-02.'::text)),
    doctor_opinion = replace(doctor_opinion, 'FDA-cleared for home hormone monitoring.', 'It is FDA-listed as a Class I home hormone test, a category exempt from FDA clearance.')
where id = 'd-initio';

